from ortak import Q, onc


def S(bolum, soru, secenekler, aciklama, sayfa, **ek):
    return Q(soru, secenekler, 0, aciklama, sayfa, bolum=bolum, **ek)


def O(bolum, onculler, kok, secenekler, dogru, aciklama, sayfa, **ek):
    return Q("", secenekler, dogru, aciklama, sayfa, onculler=onculler, kok=kok, bolum=bolum, **ek)


